import std.io
import std.string

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    if string.floatFromBits(string.floatBits(2.5)) == 2.5 { io.println("rt-a-ok") } else { io.println("rt-a-bad") }
    if string.floatFromBits(string.floatBits(0.25)) == 0.25 { io.println("rt-b-ok") } else { io.println("rt-b-bad") }
    let s = string.parseFloat("2.5e-320")
    match s {
        Some(w) => {
            if string.floatFromBits(string.floatBits(w)) == w { io.println("rt-sub-ok") } else { io.println("rt-sub-bad") }
        }
        None => { io.println("sub-none") }
    }
    return Ok(())
}
